mapper.select:
select A.* from ( select @ROWNUM := @ROWNUM + 1 as ROWNUM, TB.* from ( select faq_seq_no as faqSeqNo , faq_name as faqName , faq_content as faqContent , faq_hit_cnt as faqHitCnt , faq_date as faqDate , faq_writer as faqWriter , faq_writer_name as faqWriterName , faq_up_date as faqUpDate , faq_up_user as faqUpUser , faq_del_yn as faqDelYn , faq_del_date as faqDelDate , faq_del_user as faqDelUser from tb_faq where faq_del_yn = 'N'
and faq_name like CONCAT('%', #{searchWord}, '%')
and faq_content like CONCAT('%', #{searchWord}, '%')
and (faq_name like CONCAT('%', #{searchWord}, '%') OR faq_content like CONCAT('%', #{searchWord}, '%'))
and faq_writer_name = #{searchWord}
order by faq_seq_no DESC ) TB, ( select @ROWNUM := 0 ) R ) A where A.ROWNUM between #{startRow} and #{endRow}

mapper.update:
update tb_faq set 
	faq_hit_cnt = faq_hit_cnt + 1
where faq_seq_no = #{faqSeqNo}

mapper.insert:

	select
		case count(*) when 0 then 1 else max(faq_seq_no) + 1 end as faqSeqNo
	from tb_faq				

insert into tb_faq (
	  faq_seq_no
	, faq_name
	, faq_content
	, faq_hit_cnt
	, faq_date
	, faq_writer
	, faq_writer_name
	, faq_up_date
	, faq_up_user
	, faq_del_yn	
	, faq_del_date	
	, faq_del_user	
) values (
	#{faqSeqNo}
	, #{faqName}
	, #{faqContent}
	, 0
	, now()
	, #{faqWriter}
	, #{faqWriterName}
	, now()
	, #{faqWriter}
	, COALESCE(#{faqDelYn}, 'N')
	, now()
	, #{faqWriter}
)

mapper.update:
update tb_faq set 
		faq_name			= #{faqName}
	, 	faq_content 		= #{faqContent}
	,	faq_up_date		= now()
	,	faq_up_user		= #{faqUpUser}
where 
	faq_seq_no = #{faqSeqNo}

update tb_faq set
		faq_del_yn 	= 'Y'
	, 	faq_up_date 	= now()
	, 	faq_up_user	= #{faqUpUser}
where
	faq_seq_no = #{faqSeqNo}
